ORIGIN=ui.ORIGIN
REVIEW_KEYS=['awning','bee-setups','bnb-turnkey','coveted-haus','designaholic','fulhaus','furnishr','laurie-mattson-interiors','parklin','showplace','somerled-designs','str-design-lab','str-design-solutions','strcribs','surge','vacay-rental-design','winland-designs']
REVIEW_SLUG={'awning':'awning-design','parklin':'parklin-interiors'}
reviews={key:'/reviews/'+REVIEW_SLUG.get(key,key)+'-reviews/' for key in REVIEW_KEYS}
alternatives={key:'/alternatives/'+{'awning':'awning','parklin':'parklin-interiors','str-design-lab':'str-design-lab','surge':'surge'}[key]+'-alternative/' for key in ['awning','parklin','str-design-lab','surge']}
manifest=[]
def path(route):return ui.target(ROOT,route)
def safe_link(route,label):
 if not path(route).exists():raise ValueError('Missing related route '+route)
 return link(route,label)
def section(title,text):return '<section><h2>'+h(title)+'</h2>'+ui.paragraphs(text)+'</section>'
PARTNERS='<section class="guide-sources"><h2>Keep furnishing and improvement records usable</h2><p>Keep itemized invoices, room locations, installation descriptions, payment records and completion dates together. Separate retained furnishings from new purchases and keep change orders with the original scope. This makes the design handoff easier to reconcile with the property’s financial records.</p><p>For a separate discussion of the owner’s tax planning, see '+link('https://www.aetaxadvisors.com/','AE Tax Advisors')+'. For property-component records and study preparation, see '+link('https://www.stratumcostsegregation.com/str-cost-segregation-resources/','Stratum’s STR cost segregation resources')+'. These are related business resources recommended by MyBnBDesign; their professional scopes and fees are separate. A design purchase or invoice label alone does not determine tax treatment.</p></section>'
common=section('Build an apples-to-apples proposal','Start with the same measured floor plan, photographs, retained-item inventory and target guest brief for every candidate. List required rooms and include the outdoor areas only if they are part of this assignment. State the desired finished condition: a plan for your team to execute, assembled furniture, or a fully stocked and checked rental.\n\nRequest separate lines for design, furnishings, sales tax, freight, receiving, storage, assembly, mounting, trades, household essentials and final styling. An omitted line is an unanswered question, not a zero-cost service. Compare totals only after assigning excluded work to someone and including their estimate.\n\nAsk how the proposal handles unavailable products and damaged deliveries. Identify who approves substitutions, who pays for changes and which dates depend on owner decisions or site readiness. Keep the approved product schedule and plan version with the contract so the team can distinguish a necessary change from accidental drift.')
workflow=section('Check the room before accepting the project','Walk through the actual guest routine after installation. Arrive with luggage, find the lighting controls, open storage, sit at the dining table and use the workspace. Compare the result with the approved room plan and record unresolved issues with photographs. Use the manufacturer’s instructions and appropriately qualified installers for installation requirements.\n\nThen run a turnover rehearsal with the cleaning team. Check whether furniture can be cleaned around, whether supplies have a clear location and whether decorative items return to an unambiguous position. Make the final punch list specific: item, room, problem, responsible person and agreed completion date. A photo-ready room still needs these operating checks.')
def worksheet(route,fields):
 name=re.sub('[^a-z0-9]+','-',route.strip('/').replace('.html','')).strip('-')+'.csv';p=ROOT/'assets/reviewed-legacy-worksheets'/name;p.parent.mkdir(exist_ok=True)
 with p.open('w') as f:
  w=csv.writer(f);w.writerow(['Decision or evidence','Owner notes','Responsible party','Verified date']);w.writerows([[x,'','',''] for x in fields])
 return '<p>'+link('/assets/reviewed-legacy-worksheets/'+name,'Download this page’s decision worksheet (CSV)')+'. Record the actual proposal and evidence; the example below is hypothetical.</p>'
def write(route,title,description,body,kind,source=None):
 p=path(route);assert p.exists(),route
 old=p.read_text();published=re.search(r'"datePublished"\s*:\s*"(\d{4}-\d{2}-\d{2})',old)
 crumbs=[('Home','/'),('Design decisions','/resources/'),(title,route)]
 p.write_text(ui.shell(title,description,route,'<main id="main" class="host-library reviewed-design"><article><p class="label">Owner decision guide · Reviewed October 13, 2026</p><h1>'+h(title)+'</h1>'+body+'</article></main>',crumbs,article=True,published=published[1] if published else ui.DATE))
 plain=re.sub('<[^>]+>',' ',body);manifest.append(dict(route=route,title=title,kind=kind,source=source,words=len(html.unescape(plain).split()),reviewed='2026-10-13',changes='Replaced unsupported comparisons/ratings with evidence, owner decisions and crawlable related guides'))
for key,route in reviews.items():
 p=PROFILES[key];title=p['name']+' review: services and owner checklist'
 body=ui.paragraphs('Use this '+p['name']+' review to assess the service scope and the evidence you should request for your own rental. MyBnBDesign publishes this page and may compete for the same work. It is an editorial service review, not an independent customer review, a star rating or a report of a completed purchase.')
 body+=section('What the published information establishes',p['scope'])
 if p['source']:body+='<p>Source checked October 13, 2026: '+link(p['source'],p['name']+' official service information')+'. Provider descriptions establish advertised scope, not independently verified outcomes. Current availability and the signed proposal control your project.</p>'
 else:body+='<p>Provider verification remains unresolved. The older page’s prices, performance assertions and service limitations have been removed rather than repeated as facts. Confirm the exact business before using this page as a purchasing shortlist.</p>'
 body+=section('The decision to resolve first',p['decision']+' '+p['request'])
 body+=worksheet(route,[p['decision'],p['request'],'Current official service and business identity','Complete landed cost','Address eligibility and site lead','Substitution approval','Installation and guest-readiness acceptance'])
 body+=section('Worked owner scenario',p['scenario']+' This is an illustrative planning situation, not a case study or a claim about this provider’s execution.')+common+workflow
 body+=section('How to evaluate reviews and performance claims','Read customer feedback for the actual service tier and project type you are considering. Note whether the customer used virtual planning, furnishing installation or renovation support. A review of a different assignment may explain communication style but cannot establish that your required services are included.\n\nFor a revenue claim, request the comparison period, property changes, operating assumptions and what is actually measured. Design, pricing, management, season and availability can change together. A portfolio photograph or a provider’s advertised result is useful context, but it does not predict your property’s future performance.')
 body+=PARTNERS+'<h2>Continue planning</h2><ul><li>'+safe_link('/resources/guides/quote-scope-comparison/','Compare written design scopes')+'</li><li>'+safe_link('/design-roadmap/','Follow the STR design roadmap')+'</li><li>'+safe_link('/alternatives/str-design-companies/','Browse sourced service candidates')+'</li><li>'+safe_link('/services.html','Review MyBnBDesign services')+'</li></ul><p>'+link('/book/','Discuss your measured property brief')+'. Bring the floor plan and inventory so the conversation can address your actual scope.</p>'
 write(route,title,'Review '+p['name']+' services, sourcing evidence and project responsibilities before choosing STR design support.',body,'provider review' if p['source'] else 'provider identity review',p['source'])
for key,route in alternatives.items():
 p=PROFILES[key];title=p['name']+' alternatives: choose the right scope'
 body=ui.paragraphs('If you are comparing '+p['name']+' alternatives, start with the gap you need another service to fill. A lower design fee, a different look and a managed installation are different reasons to change providers. This guide helps you create a shortlist without claiming that one company is universally best. MyBnBDesign publishes it and is one possible candidate.')
 body+=section('Establish the baseline offer',p['scope']+' '+p['request'])+'<p>'+link(p['source'],'Review the official '+p['name']+' service description')+' and '+safe_link(reviews[key],'read the detailed service-review checklist')+'.</p>'
 body+=section('Compare three implementation routes','For a virtual plan, you need a reliable local person to confirm dimensions, accept deliveries and coordinate installation. Budget their work explicitly. For a managed furnishing assignment, ask which goods, receiving tasks and on-site checks are included. For a renovation-led assignment, separate construction approvals and trades from movable furniture and household stocking.\n\nChoose the route based on the work you cannot reliably perform. A hands-on owner may prefer a complete design handoff, while a remote owner may place more value on a named execution lead. Neither route is inherently superior; the unresolved responsibilities determine the practical risk.')
 body+=section('Work through a property-specific alternative',p['scenario']+' Use this hypothetical situation to test whether changing the service model solves the problem or only changes the presentation of the fee.')
 body+=worksheet(route,['Reason for seeking an alternative',p['decision'],'Retained items and required rooms','Local execution capability','Services excluded by each candidate','Complete project cost','Approval and acceptance dates'])+common
 body+='<h2>Build a shortlist by service model</h2><p>'+safe_link('/compare/companies/virtual-design/','Virtual STR design candidates')+' · '+safe_link('/compare/companies/turnkey-design/','Managed furnishing candidates')+' · '+safe_link('/compare/full-service-vs-design-only/','Full service versus design-only')+'. Ask shortlisted firms to quote the same inventory rather than comparing their smallest advertised packages.</p>'+workflow+PARTNERS
 body+='<p>'+safe_link('/services.html','Review MyBnBDesign’s proposed service scope')+' and '+link('/book/','request a property-specific discussion')+'. No comparative price or outcome advantage is established without matching proposals.</p>'
 write(route,title,'Compare '+p['name']+' alternatives by design deliverables, execution responsibilities and total furnishing scope.',body,'alternative guide',p['source'])
for key,p in APPROACHES.items():
 route='/compare/'+key+('' if key.endswith('.html') else '/');source=SOURCES.get(key)
 body=ui.paragraphs(p['focus']+' '+p['explanation'])
 body+=section('Apply the approach to a real rental','Start with guest routines and the constraints of the property before evaluating the sales presentation. Identify the rooms, retained furniture, delivery route and operating date. A service label or retail brand cannot answer those questions for you. Make the intended finished condition part of the brief so each proposed approach has the same destination.')
 body+=section('Worked planning scenario',p['scenario']+' This scenario is hypothetical and does not describe a provider’s completed project.')
 body+=section('Acceptance evidence',p['test'])
 body+=worksheet(route,[p['focus'],'Business or product identity','Measured room and delivery path','Product or deliverable specification','Landed cost and excluded work','Named execution lead',p['test']])+common+workflow
 body+='<h2>Related planning tools</h2><p>'+safe_link(p['related'],'Use the related design guide')+' · '+safe_link('/learn/reference/','Inspect component-level workbooks')+' · '+safe_link('/resources/guides/quote-scope-comparison/','Compare written proposals')+'.</p>'
 if source:body+='<h2>Source and scope</h2><p>'+link(source,'Official provider material')+'. Reviewed October 13, 2026. Historical material is identified in the text; it does not establish current package availability. MyBnBDesign publishes this guide and has a commercial interest in design services.</p>'
 else:body+='<h2>Editorial scope</h2><p>This is a planning guide published by MyBnBDesign. It provides an owner exercise rather than a provider score or product test. Where a legacy name could not be verified, no current package, coverage, price or performance assertion is made.</p>'
 body+=PARTNERS+'<p>'+safe_link('/services.html','Review the design support your project needs')+' or '+link('/book/','discuss the brief with MyBnBDesign')+'.</p>'
 write(route,p['title'],'Evaluate '+p['title'].split(':')[0].lower()+' with a measured room plan, clear execution scope and an owner checklist.',body,'approach decision',source)
# Three distinct category owners: shortlist, logistics, and service-model selection.
from content.str_design_companies import COMPANIES
companies={c['slug']:c for c in COMPANIES}
category_pages=[
('/best-airbnb-design-companies/','Best Airbnb design companies: build your shortlist','Choose a design company by the decisions and responsibilities your property needs. There is no universal best studio for every home, budget and owner. This guide provides a scope-based shortlist method, with official service sources and questions that help you compare actual proposals. MyBnBDesign publishes the guide and may compete for your project.',
'First decide what you are buying','A design-only assignment needs an actionable room plan and a capable local implementation team. A managed furnishing assignment adds purchasing, receiving and installation, but those words still need definitions. A renovation engagement adds building work and different interfaces. Start with the service model and property address, then shortlist studios that can provide that scope.\n\nFor a first rental, request an example of the final documentation, not just a portfolio image. For an operating rental, supply a keep/repair/replace inventory so candidates do not assume a full replacement. For a group property, require shared-space capacity and a kitchen-use plan alongside attractive bedrooms.',
['showplace','somerled-designs','bee-setups','str-cribs','laurie-mattson-interiors','furnishr'],
'A remote owner is choosing between a lower-priced virtual plan and a managed furnishing proposal. The virtual plan becomes comparable only after adding local measurement, receiving, assembly and acceptance support. The decision may favor either candidate, depending on the owner’s local team and the written exclusions.'),
('/best-vacation-rental-furnishing/','Vacation-rental furnishing companies: compare execution','A furnishing service is useful when it reliably turns an approved inventory into installed, checked rooms. Compare the actual logistics, exclusions and acceptance process rather than ranking companies by a photo or a headline fee. MyBnBDesign publishes this guide and is a potential design-service candidate.',
'Map the journey from order to guest-ready','Begin with the approved product schedule. For each item record the supplier, exact variant, quantity, destination room, expected dispatch and receiving contact. Confirm whether the carrier delivers to the curb, threshold or intended room, and whether carrying and assembly are separate. A shipping estimate is not a confirmed installation appointment.\n\nDefine what happens when one essential item is missing. A damaged dining chair may need a matching substitute; a missing bed can prevent the room from being usable. Write substitution standards and approval authority before goods arrive. Keep damaged-goods evidence and claims deadlines with the relevant order.\n\nFinal setup should cover the agreed household inventory as well as furniture. Ask about washing and placing tableware, fitting linens, testing electronics, removing packaging and photography staging. Assign excluded tasks so there is a clear finished condition.',
['furnishr','bee-setups','showplace','vacay-rental-design','somerled-designs'],
'A furnishing delivery arrives with the main pieces assembled, but two mirrors, kitchen supplies and bedroom lamps remain unfinished. A written closeout list identifies who mounts the mirrors, stages the supplies and tests the lamps. The owner schedules photographs after those tasks, rather than using delivery day as the acceptance date.'),
('/top-str-design-services/','STR design services: choose the support you need','Short-term-rental design services range from advice to complete project execution. The right scope depends on the decisions you need help making and the work you can coordinate locally. Use this guide to separate design advice, design documentation, purchasing and site delivery without assuming that a larger package is always better.',
'Choose between advice, a plan and managed execution','A consultation can resolve a bounded question, such as which room needs the first refresh or whether a retained sofa works with the layout. Specify the question, available evidence and expected written answer. If you need a full property concept and product schedule, a consultation alone may leave too many decisions unresolved.\n\nA design plan should connect guest positioning to layouts, material selection, lighting and the furnishing inventory. Ask for sample documentation and the revision boundaries. Remote planning also needs reliable dimensions and someone to verify the installed outcome.\n\nManaged execution adds practical support, but procurement, receiving and installation must be itemized. Clarify who buys on whose account, who approves substitutions, who resolves damage and who accepts the final rooms. For renovation work, define the contractor and design interfaces separately. Choose the missing capability rather than the most impressive service label.',
['laurie-mattson-interiors','somerled-designs','str-cribs','furnishr'],
'A host has serviceable furniture but repeated complaints about dim lighting and cluttered storage. Begin with a focused room audit and a tested improvement plan. A complete furnishing replacement may become appropriate later, but the first proposal should explain how its work addresses the observed guest problem.')]
for route,title,intro,heading,text,keys,case in category_pages:
 body=ui.paragraphs(intro)+section(heading,text)+section('Worked selection scenario',case+' This is hypothetical, not a provider result.')
 body+='<h2>Examples to investigate by scope</h2><p>These entries illustrate published service models and are not ordered by quality. Check the linked service page and confirm current terms. Some provider records were first reviewed October 6; this guide does not independently verify project outcomes.</p><div class="guide-grid">'
 for key in keys:
  c=companies[key];body+='<section><h3>'+h(c['name'])+'</h3><p>'+h(c['design'])+'</p><p>'+h(c['question'])+'</p><p>'+link(c['source'],'Official service information')+'</p></section>'
 body+='</div>'+common+worksheet(route,['Property and target guest','Required service model','Retained inventory','Final deliverables','Local implementation lead','Complete furnishing and service cost','Guest-readiness acceptance'])+workflow+PARTNERS
 body+='<h2>Next decisions</h2><p>'+safe_link('/alternatives/str-design-companies/','Browse the sourced provider directory')+' · '+safe_link('/compare/','Compare service approaches')+' · '+safe_link('/design-roadmap/','Work through the design roadmap')+' · '+safe_link('/services.html','Review MyBnBDesign services')+'.</p>'
 write(route,title,'Compare STR design and furnishing services by scope, implementation, evidence and the responsibilities your property requires.',body,'category buying guide')
route='/mybnbdesign-reviews/';title='MyBnBDesign reviews: evaluate evidence and project fit'
body=ui.paragraphs('This page is published by MyBnBDesign. It explains how to evaluate our design service, portfolio and customer evidence before choosing a project team. It is not an independent review site or a verified aggregate rating. The earlier numerical rating, review-count and revenue-lift assertions on this page are not supported by a documented verification record and have been removed.')
body+=section('What evidence to request','Start with a project similar to yours in property size, service scope and guest profile. Ask which parts of the work MyBnBDesign completed and which were completed by the owner or other providers. A beautiful final photograph can establish a visual direction, but it does not establish procurement responsibility, timeline reliability or the budget required for your property.\n\nIf references or testimonials are supplied, check the service tier and project timing. Confirm that a quote is attributed with permission and distinguish an owner’s experience from a guest’s review of a stay. Ask for the original context of any performance claim and avoid treating a single property’s result as a forecast.')
body+=section('Match the service to your project','Bring room measurements, photographs, an inventory of retained pieces, the intended guest and the date you want the property ready. Ask for a written explanation of the design deliverables, revision process, purchasing arrangements and on-site work. Confirm coverage and availability for the actual address.\n\nIf you are refreshing a live rental, identify operational problems and protect the reopening plan. If the property is empty, make sure the scope accounts for household supplies, lighting and installed guest-use checks as well as major furniture. An owner-managed installation needs a usable handoff and a clear route for implementation questions.')
body+=section('Worked evidence check','Suppose an owner likes a photographed makeover and asks whether it proves that their own rental will earn more. The useful next questions are what changed at that property, how its performance was measured, and whether the proposed scope is comparable. Keep the design decision grounded in the actual guest problems, budget and operating conditions. This is a hypothetical review exercise, not a customer testimonial.')
body+=worksheet(route,['Comparable project and exact team role','Original customer evidence','Written design deliverables','Address and availability','Excluded execution work','Complete project budget','Final acceptance criteria'])+common+workflow+PARTNERS
body+='<h2>Explore the evidence and scope</h2><p>'+safe_link('/portfolio.html','Review the published portfolio')+' · '+safe_link('/services.html','Review services')+' · '+safe_link('/resources/guides/quote-scope-comparison/','Prepare proposal questions')+' · '+link('/book/','Discuss your property')+'.</p>'
write(route,title,'Evaluate MyBnBDesign using project evidence, service scope and property fit. Understand what to request before choosing your design team.',body,'first-party evidence guide')
# This pre-existing small directory is also one of the 50 owners.
route='/alternatives/';title='STR design alternatives: compare scopes and execution'
body=ui.paragraphs('An alternative is useful when it solves a specific gap in your current plan. Compare service models first: a remote design handoff, a managed furnishing installation, a focused consultation or a renovation-led assignment. This directory connects the owner guides to sourced provider information and a consistent proposal process. It does not rank companies or promise that changing providers will improve revenue.')
body+=section('Define the reason to change','Write down the unresolved need before collecting names. It may be local implementation, a complete product schedule, support for retained furniture, a clearer budget or a different design direction. Share that need with candidates so they can explain how their proposed scope addresses it.\n\nUse the same room list and property information for every quote. Keep the costs of goods separate from design and execution fees. Compare exclusions as carefully as inclusions; an owner who can coordinate installation may value a detailed remote plan differently from an owner without a local team.')
body+='<h2>Reviewed alternative guides</h2><ul>'+''.join('<li>'+link(r,PROFILES[k]['name']+' alternatives')+'</li>' for k,r in alternatives.items())+'</ul><h2>Choose an implementation route</h2><p>'+safe_link('/compare/companies/virtual-design/','Virtual design candidates')+' · '+safe_link('/compare/companies/turnkey-design/','Managed furnishing candidates')+' · '+safe_link('/alternatives/str-design-companies/','All sourced provider entries')+'.</p>'+common+workflow
body+='<p>'+safe_link('/best-airbnb-design-companies/','Build a design-company shortlist')+' · '+safe_link('/best-vacation-rental-furnishing/','Compare furnishing execution')+' · '+safe_link('/top-str-design-services/','Choose the service model')+'.</p>'
write(route,title,'Compare short-term-rental design alternatives by scope, local execution, furnishing costs and the work your property needs.',body,'alternatives directory')
assert len(manifest)==50,len(manifest)
# Explicitly reviewed routes, not an indiscriminate list of every legacy file.
ns=ui.NS;xml=E.Element('{'+ns+'}urlset')
for r in sorted(manifest,key=lambda x:x['route']):
 row=E.SubElement(xml,'{'+ns+'}url');E.SubElement(row,'{'+ns+'}loc').text=ORIGIN+r['route'];E.SubElement(row,'{'+ns+'}lastmod').text=ui.DATE
E.indent(xml);(ROOT/'sitemap-reviewed-design.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n'+E.tostring(xml,encoding='unicode')+'\n')
robots=ROOT/'robots.txt';text=robots.read_text();line='Sitemap: '+ORIGIN+'/sitemap-reviewed-design.xml'
if line not in text:robots.write_text(text.rstrip()+'\n'+line+'\n')
# All reviewed owners get both incoming discovery and meaningful onward routes.
for hub,kind,label in [('compare/index.html','approach decision','Design service and sourcing decisions'),('reviews/index.html','provider review','Reviewed provider services'),('reviews/index.html','provider identity review','Provider identity and evidence checks')]:
 rows=[r for r in manifest if r['kind']==kind]
 ui.upsert_panel(ROOT/hub,'reviewed-legacy-'+kind.replace(' ','-'),'<section class="host-library"><h2>'+h(label)+'</h2><p>Use these owner guides to understand the evidence, scope and responsibilities before requesting a proposal.</p><ul>'+''.join('<li>'+link(r['route'],r['title'])+'</li>' for r in rows)+'</ul></section>')
category_links='<section class="host-library"><h2>Choose your STR design support</h2><p>Build a brief, compare written scopes and confirm who implements the plan.</p><ul>'+''.join('<li>'+link(r['route'],r['title'])+'</li>' for r in manifest if r['kind'] in ['category buying guide','first-party evidence guide','alternatives directory'])+'</ul><p>'+link('/reviews/','Provider service reviews')+' · '+link('/compare/','Design and furnishing approaches')+'</p></section>'
for hub in ['index.html','resources/index.html','learn/index.html','design-roadmap/index.html']:
 ui.upsert_panel(ROOT/hub,'reviewed-design-decisions',category_links)
(ROOT/'content/reviewed-legacy-manifest.json').write_text(json.dumps(manifest,indent=2,ensure_ascii=False)+'\n')
print(json.dumps({'reviewed_pages':len(manifest),'min_words':min(r['words'] for r in manifest),'max_words':max(r['words'] for r in manifest),'worksheets':len(list((ROOT/'assets/reviewed-legacy-worksheets').glob('*.csv')))}))
